export function getQuestionDuJour(langue = 'fr') {
  const dayOfYear = Math.floor(
    (Date.now() - new Date(new Date().getFullYear(), 0, 0)) / 86400000
  );
  const index = (dayOfYear - 1) % QUESTIONS.length;
  const q = QUESTIONS[index];
  return q;
}

export function getQuestionByJour(jour) {
  return QUESTIONS.find((item) => item.jour === jour) || QUESTIONS[0];
}

// Faille themes → question themes mapping
const FAILLE_THEME_MAP = {
  communication:  ['communication'],
  ambiance:       ['communication', 'intimite'],
  intimite:       ['intimite'],
  spiritualite:   ['spiritualite'],
  reconstruction: ['famille', 'gratitude'],
};

const ALL_THEMES = ['communication', 'spiritualite', 'projets', 'gratitude', 'famille', 'intimite', 'croissance'];

// Builds an ordered array of question IDs prioritising faille themes.
// Returns default order when failles is empty.
export function buildQuestionsOrder(failles) {
  if (!failles || failles.length === 0) {
    return QUESTIONS.map(q => q.id);
  }

  // Group all question IDs by theme
  const byTheme = {};
  QUESTIONS.forEach(q => {
    if (!byTheme[q.theme]) byTheme[q.theme] = [];
    byTheme[q.theme].push(q.id);
  });

  // Determine priority themes from failles (no duplicates)
  const priorityThemes = [];
  failles.forEach(f => {
    (FAILLE_THEME_MAP[f.theme] || []).forEach(t => {
      if (!priorityThemes.includes(t)) priorityThemes.push(t);
    });
  });

  const remainingThemes = ALL_THEMES.filter(t => !priorityThemes.includes(t));
  const allOrdered = [...priorityThemes, ...remainingThemes];

  // Cycling pools per theme
  const pools = {};
  ALL_THEMES.forEach(t => { pools[t] = { items: byTheme[t] || [], idx: 0 }; });

  const pick = (theme) => {
    const p = pools[theme];
    if (!p || p.items.length === 0) return null;
    const id = p.items[p.idx % p.items.length];
    p.idx++;
    return id;
  };

  const result = [];
  let day = 0;

  while (result.length < QUESTIONS.length && day < 5000) {
    const pos = day % 28;
    let theme;
    if (pos < 7) {
      theme = priorityThemes[0] || allOrdered[0];
    } else if (pos < 14) {
      theme = priorityThemes[1] || priorityThemes[0] || allOrdered[0];
    } else if (pos < 21) {
      theme = priorityThemes[2] || priorityThemes[0] || allOrdered[0];
    } else {
      theme = allOrdered[(pos - 21) % allOrdered.length];
    }
    const id = pick(theme);
    if (id) result.push(id);
    day++;
  }

  return result.slice(0, QUESTIONS.length);
}
